from collections import deque
A=[[0]*14 for _ in range(15)]; A[0][6]=2
for r,row in {2:[8,8,8,8,0,8,8,8,8,8,8,8,8,8],4:[8,8,0,8,8,8,8,0,8,8,8,0,8,8],7:[8,8,0,8,8,8,8,8,8,0,8,8,8,8],10:[8,8,8,8,0,8,8,0,8,8,8,0,8,8]}.items():A[r]=row
seed=(0,6)
# eligible nodes are 0s immediately adjacent to an 8 barrier, enabling a channel path; seed included.
elig={seed}
for r in range(15):
 for c in range(14):
  if A[r][c]==0 and any(0<=r+dr<15 and 0<=c+dc<14 and A[r+dr][c+dc]==8 for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]):elig.add((r,c))
q=deque([seed]);seen={seed}
while q:
 r,c=q.popleft()
 for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
  n=(r+dr,c+dc)
  if n in elig and n not in seen:seen.add(n);q.append(n)
# Keep only nodes in corridors that maintain proximity to some barrier, plus seed.
for r in range(15):
 print(''.join('2' if (r,c) in seen and A[r][c]==0 else str(A[r][c]) for c in range(14)))
print(len(seen))
